INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES
(2077,0,0,'You\'ll find the trainer inside of Aldrassil, $n.',12,0,100,0,0,0,49664,0,'Melithar Staghelm'),
(2079,0,0,'I\'m sorry, Huntress. None of our new $cs are ready. They still have much to learn.',12,0,100,0,0,0,49681,0,'Ilthalaine'),
(2079,1,0,'You\'ll find the trainer inside of Aldrassil, $n.',12,0,100,0,0,0,49664,0,'Ilthalaine'),
(2081,0,0,'Some of our huntresses have already made their way to Ban\'ethil Barrow Den. They will find you when you get inside. Go ahead and speak to Citarre to secure a ride there.',12,0,100,0,0,0,34694,0,'Sentinel Kyra Starsong'),
(3514,0,0,'Greetings, $c.',12,0,100,2,0,0,13306,0,'Tenaron Stormgrip'),
(3514,1,0,'Take with you the blessing of the wind\'s embrace. May it make your descent from Aldrassil more... direct.',12,0,100,1,0,0,34602,0,'Tenaron Stormgrip'),
(34574,0,0,'%s fades into existence as you approach, nodding a subtle greeting.',16,0,100,0,0,0,34832,0,'Shade of the Kaldorei'),
(34574,1,0,'Much has changed for our people since the Battle of Mount Hyjal.',12,0,100,1,0,0,34792,0,'Shade of the Kaldorei'),
(34574,2,0,'Nordrassil lies a pale shadow of what it once was, its power used to defeat Archimonde and drive back the Burning Legion.',12,0,100,1,0,0,34793,0,'Shade of the Kaldorei'),
(34574,3,0,'Our immortality-the very essence of our beings!-was lost.',12,0,100,1,0,0,34794,0,'Shade of the Kaldorei'),
(34574,4,0,'The Betrayer was freed from his prison, and Shand\'do Stormrage disappeared into the emerald dream.',12,0,100,1,0,0,34795,0,'Shade of the Kaldorei'),
(34574,5,0,'A dark time for all.',12,0,100,1,0,0,34796,0,'Shade of the Kaldorei'),
(34574,6,0,'The Shade of the Kaldorei closes its eyes and fades away.',16,0,100,0,0,0,34820,0,'Shade of the Kaldorei'),
(34583,0,0,'%s stares into the moonwell, lost in distant memories.',16,0,100,0,0,0,34819,0,'Shade of the Kaldorei'),
(34583,1,0,'The Arch Druid approached the dragons for their blessings, as the dragons had placed on Nordrassil in ancient times.',12,0,100,1,0,0,34801,0,'Shade of the Kaldorei'),
(34583,2,0,'But Nozdormu, Lord of Time, refused to give his blessing, chiding the druid for his arrogance.',12,0,100,1,0,0,34802,0,'Shade of the Kaldorei'),
(34583,3,0,'In agreement, Alexstrasza also refused Staghelm, and without her blessing, Teldrassil\'s growth has been flawed and unpredictable.',12,0,100,1,0,0,34803,0,'Shade of the Kaldorei'),
(34583,4,0,'Staghelm retreated to his enclave in Darnassus, ever seeking a new direction by which to bless Teldrassil, and restore the immortality of our people.',12,0,100,1,0,0,34804,0,'Shade of the Kaldorei'),
(34583,5,0,'The Shade of the Kaldorei closes its eyes and fades away.',16,0,100,0,0,0,34820,0,'Shade of the Kaldorei'),
(34584,0,0,'%s approaches the moonwell slowly, a familiar, thoughtful look upon its face.',16,0,100,0,0,0,34834,0,'Shade of the Kaldorei'),
(34584,1,0,'Over time, Staghelm only grew more disconnected from our people.',12,0,100,1,0,0,34805,0,'Shade of the Kaldorei'),
(34584,2,0,'Some pose that he blames us, his people, for the loss of his son, long ago during the War of the Shifting Sands.',12,0,100,1,0,0,34806,0,'Shade of the Kaldorei'),
(34584,3,0,'Others cite rumors of his escalating conflicts with Tyrande Whisperwind, the shining light of our people, our leader in Darnassus.',12,0,100,1,0,0,34807,0,'Shade of the Kaldorei'),
(34584,4,0,'But many druids of the Cenarion Circle stand firm that he wants only what is best for all of the Kaldorei, and serve him unerringly towards that end.',12,0,100,1,0,0,34808,0,'Shade of the Kaldorei'),
(34584,5,0,'Fandral Staghelm carries the burden of our sins and our follies, and in so doing deserves the respect of us all.',12,0,100,1,0,0,34809,0,'Shade of the Kaldorei'),
(34584,6,0,'The Shade of the Kaldorei closes its eyes and fades away.',16,0,100,66,0,0,34820,0,'Shade of the Kaldorei'),
(34585,0,0,'%s rests on the side of the moonwell in peaceful contemplation.',16,0,100,0,0,0,34833,0,'Shade of the Kaldorei'),
(34585,1,0,'In weeks past, all of those living atop Teldrassil have found their memories blurry, as if time itself seized a portion of their lives.',12,0,100,1,0,0,34810,0,'Shade of the Kaldorei'),
(34585,2,0,'We break from this haze to find that Fandral Staghelm and many of his closest followers have disappeared without a word.',12,0,100,1,0,0,34811,0,'Shade of the Kaldorei'),
(34585,3,0,'But in his place, Shan\'do Stormrage awoke from the dream and returned to his beloved Tyrande Whisperwind.',12,0,100,1,0,0,34812,0,'Shade of the Kaldorei'),
(34585,4,0,'And with his return came Alexstrasza and Ysera, to at long last offer their blessings upon Teldrassil',12,0,100,1,0,0,34813,0,'Shade of the Kaldorei'),
(34585,5,0,'Though a small corruption lingers, desperately longing to be cleansed, the boughs of Teldrassil itself seem changed. Growth has begun anew.',12,0,100,1,0,0,34814,0,'Shade of the Kaldorei'),
(34585,6,0,'None know what to expect next, but with Malfurion and Tyrande reunited, a new hope dawns on the Kaldorei.',12,0,100,1,0,0,34815,0,'Shade of the Kaldorei'),
(34585,7,0,'Hope for lasting relief from the shadow that has been cast on our people for so long.',12,0,100,1,0,0,44123,0,'Shade of the Kaldorei'),
(34585,8,0,'The Shade of the Kaldorei closes its eyes and fades away.',16,0,100,0,0,0,34820,0,'Shade of the Kaldorei'),
(34586,0,0,'%s smiles at you knowingly as it approaches.',16,0,100,0,0,0,34835,0,'Shade of the Kaldorei'),
(34586,1,0,'With Malfurion Stormrage gone, the druids were left in disarray and in desperate need of a new leader.',12,0,100,1,0,0,34797,0,'Shade of the Kaldorei'),
(34586,2,0,'Arch Druid Fandral Staghelm roused the druids and convinced the Circle of Ancients in Darkshore that it was time for our people to rebuild.',12,0,100,1,0,0,34798,0,'Shade of the Kaldorei'),
(34586,3,0,'In an effort to regain immortality for our people, and with the approval of the Circle, Staghelm and the most powerful druids grew Teldrassil, upon whose boughs you now stand.',12,0,100,1,0,0,34799,0,'Shade of the Kaldorei'),
(34586,4,0,'Though we have our new home, our immortal lives have not been restored.',12,0,100,1,0,0,34800,0,'Shade of the Kaldorei'),
(34586,5,0,'The Shade of the Kaldorei closes its eyes and fades away.',16,0,100,0,0,0,34820,0,'Shade of the Kaldorei'),
(49477,0,0,'I fear time may not be on our side, Ilthalaine. The battle may carry to Teldrassil itself if we do not act soon.',12,0,100,0,0,0,49682,0,'Huntress Sandrya Moonfall'),
(49478,0,0,'We will leave you to your training, Ilthalaine. This is your area of expertise.',12,0,100,0,0,0,49683,0,'Dentaria Silverglade'),
(49478,1,0,'Study well, $n. We may need you fighting by our side before the next moon fills.',12,0,100,0,0,0,49684,0,'Dentaria Silverglade'),
(49479,0,0,'Iverron\'s poison is cured, but it will take some time for him to recover.',12,0,100,0,0,0,49668,0,'Dentaria Silverglade'),
(49479,1,0,'Shadowthread Cave lies to the north. Be careful, it\'s dangerous there of late.',12,0,100,0,0,0,49665,0,'Dentaria Silverglade'),
(49479,2,0,'The moonwell is to the northeast, on the other side of the pool and up the hill.',12,0,100,0,0,0,49666,0,'Dentaria Silverglade'),
(49479,3,0,'The ramp up to Aldrassil is just in sight over there. Circle around and find Tenaron up top.',12,0,100,0,0,0,49667,0,'Dentaria Silverglade'),
(49480,0,0,'You\'ve come to help, $c? Let us stay together for a while.',12,0,100,0,0,0,49550,0,'Tarindrella'),
(49480,1,0,'The corruption goes much further than these spiders. I fear the true source is not within this cave.',12,0,100,0,0,0,49673,0,'Tarindrella'),
(49480,1,1,'His body screams for death, but his soul',12,0,100,0,0,0,49672,0,'Tarindrella'),
(49480,1,2,'I weep at these atrocities we commit. It is almost unbearable.',12,0,100,0,0,0,49674,0,'Tarindrella'),
(49480,1,3,'Corruption this deep could not have come from outside.',12,0,100,0,0,0,49675,0,'Tarindrella'),
(49480,1,4,'It almost seems as if he was born with this corruption inside of him.',12,0,100,0,0,0,49676,0,'Tarindrella'),
(49480,1,5,'They are surely unredeemable, but it still hurts to see them die.',12,0,100,0,0,0,49670,0,'Tarindrella'),
(49480,1,6,'The corruption is buried deep within him.',12,0,100,0,0,0,49669,0,'Tarindrella'),
(49480,2,0,'This totem has been corrupting the eggs! It seems a greater threat looms. The Gnarlpine remain tainted by something most foul.',12,0,100,0,0,0,49697,0,'Tarindrella'),
(49480,3,0,'My dear friends... I\'m sorry..',12,0,100,0,0,0,49671,0,'Tarindrella'),
(49480,4,0,'I\'m going to stay and do what I can to free these spiders. Thank you for your help, $n.',12,0,100,0,0,0,49549,0,'Tarindrella');
